function evidenciaResumen() { const rs = ESC.rondas.map(r => ({ r, i:indicadores(r.id) })); return rs.map(x => `${x.r.id}: ${x.i.registros} registros, ${x.i.actividades} actividades, ${x.i.reprocesos} reprocesos, ${x.i.excepciones} excepciones, ${x.i.desacuerdos} desacuerdos`).join(" · ") + ` · valoraciones: ${vigentes().filter(r => r.tipo === "valoracion").length} · observaciones: ${vigentes().filter(r => r.tipo === "observacion").length}`; }

