  const preg = vigentes().filter(r => r.tipo === "preguntas"); const barreras = {}; preg.forEach(r => (r.payload.P3 || []).forEach(k => { if (k !== "ninguna") { barreras[k] = barreras[k] || { n:0, quien:[] }; barreras[k].n++; barreras[k].quien.push(nom(r.actor) + " (" + r.ronda + ")"); } }));
