  const keys = ["actividades","suficiente","parcial","insuficiente","finalidadesNoAutorizadas","piezasDenegadas","reprocesos","solicitudes","respuestas","acusesSimulados","notificacionesSinAcuse","excepciones","diasVirtuales","mpSabe","mpGestiones","desacuerdos"]; const indRows = keys.map(k => [k].concat(ESC.rondas.map(r => ind[r.id][k])).concat([FORMULAS[k] || "conteo directo de registros"])); TABLAS.indicadores = { cols:["Indicador"].concat(ESC.rondas.map(r => r.id + " (" + r.modo + ")")).concat(["Cómo se calcula"]), rows:indRows };
