function csvDe(id) { const t = TABLAS[id]; if (!t) return ""; const q = v => { let s = String(v == null ? "" : v); if (typeof v === "string" && /^[=+\-@\t\r]/.test(s)) s = "'" + s; return '"' + s.replace(/"/g, '""') + '"'; }; return [t.cols.map(q).join(";")].concat(t.rows.map(r => r.map(q).join(";"))).join("\r\n"); }
